<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { BookOpen, FolderOpen, ClipboardList, Users, LogOut, Plus, Download, RefreshCw, Upload, ChevronLeft, KeyRound, MessageSquare, Send, Square, Paperclip, FileText, ExternalLink } from 'lucide-vue-next'
import { api, download, streamAgent, uploadAgentAttachment, type Me, type Course, type Material, type Assignment, type Submission, type Member, type FileInfo, type AgentThread, type AgentMessage, type AgentCitation, type AgentArtifact } from './api'

const me = ref<Me|null>(null), courses = ref<Course[]>([]), selected = ref<Course|null>(null)
const materials = ref<Material[]>([]), assignments = ref<Assignment[]>([]), members = ref<Member[]>([])
const currentAssignment = ref<Assignment|null>(null), submissions = ref<Submission[]>([])
const tab = ref<'materials'|'assignments'|'members'|'agent'>('materials'), authMode = ref<'login'|'register'|'reset'>('login')
const email = ref(''), password = ref(''), displayName = ref(''), code = ref(''), invite = ref('')
const courseName = ref(''), courseIcon = ref<File|null>(null), joinCode = ref(''), materialTitle = ref(''), materialFile = ref<File|null>(null)
const assignmentTitle = ref(''), description = ref(''), dueAt = ref(''), allowLate = ref(false), extensions = ref(''), maxMb = ref(50), assignmentFile = ref<File|null>(null), submissionFile = ref<File|null>(null)
const message = ref(''), busy = ref(false), panel = ref<'none'|'create'|'join'|'invite'|'material'|'assignment'>('none')
const agentThreads = ref<AgentThread[]>([]), activeThread = ref<AgentThread|null>(null), agentMessages = ref<AgentMessage[]>([])
const agentDraft = ref(''), agentUseMaterials = ref(false), agentBusy = ref(false), agentStreaming = ref(''), agentRunId = ref<number|null>(null)
const agentFile = ref<File|null>(null), agentAttachment = ref<{id:number;name:string;size:number;mime_type:string}|null>(null)
const isTeacher = computed(() => selected.value?.role === 'teacher')
const fmt = (date: string) => new Date(date).toLocaleString('zh-CN', { dateStyle: 'medium', timeStyle: 'short' })
const size = (bytes: number) => bytes < 1024 * 1024 ? `${Math.ceil(bytes/1024)} KB` : `${(bytes/1024/1024).toFixed(1)} MB`
async function run(task: () => Promise<void>) { busy.value = true; message.value = ''; try { await task() } catch(e) { message.value = e instanceof Error ? e.message : '操作失败' } finally { busy.value = false } }
async function refreshUser() { me.value = await api<Me>('me/'); courses.value = await api<Course[]>('courses/') }
async function start() { await api('csrf/'); try { await refreshUser() } catch { me.value = null } }
onMounted(start)
async function authenticate() { await run(async () => { if (authMode.value === 'register') await api('auth/register/', 'POST', { email:email.value, display_name:displayName.value, password:password.value, code:code.value }); else if (authMode.value === 'reset') { await api('auth/reset/', 'POST', { email:email.value, password:password.value, code:code.value }); authMode.value = 'login'; message.value = '密码已重置，请登录'; return } else await api('auth/login/', 'POST', { email:email.value, password:password.value }); await refreshUser() }) }
async function sendCode() { await run(async () => { await api('auth/code/', 'POST', { email:email.value, purpose:authMode.value === 'reset' ? 'reset' : 'register' }); message.value = '验证码已发送，请查看邮箱' }) }
async function signOut() { await run(async () => { await api('auth/logout/', 'POST'); me.value = null; selected.value = null }) }
async function selectCourse(course: Course) { selected.value = course; currentAssignment.value = null; tab.value = 'materials'; await loadTab() }
async function loadTab() { if (!selected.value) return; const id = selected.value.id; if (tab.value === 'materials') materials.value = await api<Material[]>(`courses/${id}/materials/`); if (tab.value === 'assignments') assignments.value = await api<Assignment[]>(`courses/${id}/assignments/`); if (tab.value === 'members') members.value = await api<Member[]>(`courses/${id}/members/`); if (tab.value === 'agent') await loadAgent() }
async function switchTab(value: 'materials'|'assignments'|'members'|'agent') { tab.value = value; currentAssignment.value = null; await run(loadTab) }
async function loadAgent() { if (!selected.value) return; agentThreads.value = await api<AgentThread[]>('agent/threads/'); const courseThreads = agentThreads.value.filter(t => t.course_id === selected.value!.id); agentThreads.value = courseThreads; const current = activeThread.value ? courseThreads.find(t => t.id === activeThread.value!.id) : null; activeThread.value = current || courseThreads[0] || null; agentMessages.value = activeThread.value ? await api<AgentMessage[]>(`agent/threads/${activeThread.value.id}/messages/`) : [] }
async function newAgentThread() { if (!selected.value) return; activeThread.value = await api<AgentThread>('agent/threads/', 'POST', { course_id: selected.value.id }); agentThreads.value.unshift(activeThread.value); agentMessages.value = [] }
function agentFileFrom(event: Event) { agentFile.value = (event.target as HTMLInputElement).files?.[0] || null; agentAttachment.value = null }
async function sendAgent() { if (!selected.value || !agentDraft.value.trim() || agentBusy.value) return; agentBusy.value = true; message.value = ''; try { if (!activeThread.value) await newAgentThread(); if (agentFile.value) { agentAttachment.value = await uploadAgentAttachment(agentFile.value, selected.value.id); agentFile.value = null } const content = agentDraft.value.trim(); agentDraft.value = ''; agentStreaming.value = ''; const attachments = agentAttachment.value ? [agentAttachment.value.id] : []; const attached = agentAttachment.value; agentAttachment.value = null; agentMessages.value.push({id:Date.now(),role:'user',content,citations:[],attachments:attached?[{id:attached.id,name:attached.name,mime_type:attached.mime_type}]:[],metadata:{},created_at:new Date().toISOString()}); await streamAgent(`agent/threads/${activeThread.value!.id}/messages/stream/`, { content, use_course_materials: agentUseMaterials.value, attachments }, { onEvent: (type, payload) => { if (type === 'message_start') agentRunId.value = payload.run_id; if (type === 'delta') agentStreaming.value += payload.text || ''; if (type === 'message_end') agentStreaming.value = ''; if (type === 'error') message.value = payload.error || '生成失败' } }); agentStreaming.value = ''; await loadAgent() } catch (error) { message.value = error instanceof Error ? error.message : '生成失败' } finally { agentBusy.value = false; agentRunId.value = null } }
async function stopAgent() { if (!agentRunId.value) return; await api(`agent/runs/${agentRunId.value}/cancel/`, 'POST'); message.value = '已请求停止生成，正在保存已生成内容' }
async function createAgentArtifact(kind: 'pdf'|'docx') { if (!activeThread.value || !agentMessages.value.length) return; const latest = [...agentMessages.value].reverse().find(item => item.role === 'assistant'); if (!latest) return; await run(async () => { const artifact = await api<AgentArtifact>(`agent/threads/${activeThread.value!.id}/artifacts/`, 'POST', { kind, title: latest.content.slice(0, 40), content: latest.content }); window.open(artifact.preview_url, '_blank') }) }
async function createCourse() { await run(async () => { const form = new FormData(); form.append('name', courseName.value); if (courseIcon.value) form.append('icon', courseIcon.value); const c = await api<Course>('courses/', 'POST', form); courses.value.unshift(c); panel.value = 'none'; courseName.value = ''; courseIcon.value = null; await selectCourse(c) }) }
async function joinCourse() { await run(async () => { const c = await api<Course>('courses/join/', 'POST', {code:joinCode.value}); courses.value.unshift(c); panel.value = 'none'; joinCode.value = ''; await selectCourse(c) }) }
async function redeem() { await run(async () => { await api('teacher-invite/redeem/', 'POST', {code:invite.value}); await refreshUser(); panel.value = 'none'; invite.value = ''; message.value = '教师资格已开通' }) }
async function resetCode() { if (!selected.value || !confirm('重置后旧课程码立即失效，确定继续？')) return; await run(async () => { const result = await api<{join_code:string}>(`courses/${selected.value!.id}/code/reset/`, 'POST'); selected.value!.join_code = result.join_code; message.value = '课程码已重置' }) }
function fileFrom(event: Event, target: 'icon'|'material'|'assignment'|'submission') { const f = (event.target as HTMLInputElement).files?.[0] || null; if (target === 'icon') courseIcon.value = f; else if (target === 'material') materialFile.value = f; else if (target === 'assignment') assignmentFile.value = f; else submissionFile.value = f }
async function uploadMaterial() { if (!selected.value || !materialFile.value) { message.value = '请选择文件'; return } await run(async () => { const form = new FormData(); form.append('file', materialFile.value!); form.append('title', materialTitle.value); await api(`courses/${selected.value!.id}/materials/`, 'POST', form); materialTitle.value = ''; materialFile.value = null; panel.value = 'none'; await loadTab() }) }
async function publish() { if (!selected.value) return; await run(async () => { const form = new FormData(); form.append('title', assignmentTitle.value); form.append('description', description.value); form.append('due_at', new Date(dueAt.value).toISOString()); form.append('allow_late', String(allowLate.value)); form.append('allowed_extensions', extensions.value); form.append('max_file_size_mb', String(maxMb.value)); if (assignmentFile.value) form.append('file', assignmentFile.value); await api(`courses/${selected.value!.id}/assignments/`, 'POST', form); assignmentTitle.value = ''; description.value = ''; assignmentFile.value = null; panel.value = 'none'; await loadTab() }) }
async function openAssignment(a: Assignment) { await run(async () => { currentAssignment.value = await api<Assignment>(`assignments/${a.id}/`); if (isTeacher.value) submissions.value = await api<Submission[]>(`assignments/${a.id}/submissions/`) }) }
async function submit() { if (!currentAssignment.value || !submissionFile.value) { message.value = '请选择作业文件'; return } await run(async () => { const form = new FormData(); form.append('file', submissionFile.value!); await api(`assignments/${currentAssignment.value!.id}/submit/`, 'POST', form); submissionFile.value = null; await openAssignment(currentAssignment.value!); message.value = '提交成功' }) }
async function getFile(file: FileInfo) { await run(async () => download(file)) }
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">C</span><span>CampusClaw</span></div>
      <template v-if="me">
        <div class="sidebar-section">我的课程 <span>{{ courses.length }}</span></div>
        <nav class="course-nav"><button v-for="c in courses" :key="c.id" :class="{active:selected?.id===c.id}" @click="selectCourse(c)"><BookOpen :size="17"/><span>{{ c.name }}</span></button></nav>
        <div class="sidebar-actions"><button @click="panel='join'"><Plus :size="17"/> 加入课程</button><button v-if="me.can_create_course" @click="panel='create'"><Plus :size="17"/> 创建课程</button><button v-else @click="panel='invite'"><KeyRound :size="17"/> 兑换教师邀请码</button></div>
        <div class="sidebar-user"><div class="avatar">{{ me.display_name.slice(0,1) }}</div><div class="user-copy"><strong>{{ me.display_name }}</strong><small>{{ me.email }}</small></div><button title="退出登录" aria-label="退出登录" @click="signOut"><LogOut :size="18"/></button></div>
      </template>
    </aside>
    <main class="main">
      <template v-if="!me"><div class="auth-wrap"><div class="auth-heading"><h1>{{ authMode==='login'?'登录 CampusClaw':authMode==='register'?'创建账号':'重置密码' }}</h1><p>进入你的课程空间</p></div><form @submit.prevent="authenticate"><label>邮箱<input v-model="email" type="email" required autocomplete="email" placeholder="name@example.com"></label><label v-if="authMode==='register'">姓名<input v-model="displayName" required maxlength="80" placeholder="你的姓名"></label><label v-if="authMode!=='login'">验证码<div class="inline-input"><input v-model="code" required inputmode="numeric" maxlength="6" placeholder="6 位验证码"><button type="button" class="secondary" :disabled="busy || !email" @click="sendCode">发送验证码</button></div></label><label>密码<input v-model="password" type="password" required minlength="8" autocomplete="current-password" placeholder="至少 8 位"></label><button class="primary full" :disabled="busy">{{ authMode==='login'?'登录':authMode==='register'?'注册':'重置密码' }}</button></form><div class="auth-links"><button @click="authMode='login'">登录</button><button @click="authMode='register'">注册</button><button @click="authMode='reset'">忘记密码</button></div></div></template>
      <template v-else-if="!selected"><header class="page-header"><div><h1>课程</h1><p>选择课程开始工作</p></div><button class="primary" @click="panel='join'"><Plus :size="17"/> 加入课程</button></header><div v-if="courses.length" class="course-grid"><button v-for="c in courses" :key="c.id" class="course-tile" @click="selectCourse(c)"><span class="course-icon"><img v-if="c.icon" :src="c.icon" alt=""><template v-else>{{ c.name.slice(0,1) }}</template></span><strong>{{ c.name }}</strong><small>{{ c.role==='teacher'?'教师':'学生' }} · {{ c.member_count }} 位成员</small></button></div><div v-else class="empty"><BookOpen :size="34"/><h2>还没有课程</h2><p>输入课程码加入，或兑换邀请码后创建课程。</p></div></template>
      <template v-else><header class="page-header course-header"><div><button class="back" @click="selected=null"><ChevronLeft :size="16"/> 所有课程</button><h1>{{ selected.name }}</h1><p>{{ isTeacher?'教师':'学生' }} · {{ selected.member_count }} 位成员</p></div><div v-if="isTeacher" class="join-code"><span>课程码</span><strong>{{ selected.join_code }}</strong><button title="重置课程码" aria-label="重置课程码" @click="resetCode"><RefreshCw :size="16"/></button></div></header>
        <div class="tabs"><button :class="{active:tab==='agent'}" @click="switchTab('agent')"><MessageSquare :size="17"/> Agent</button><button :class="{active:tab==='materials'}" @click="switchTab('materials')"><FolderOpen :size="17"/> 课程资料</button><button :class="{active:tab==='assignments'}" @click="switchTab('assignments')"><ClipboardList :size="17"/> 作业</button><button :class="{active:tab==='members'}" @click="switchTab('members')"><Users :size="17"/> 成员</button></div>
        <section v-if="tab==='agent'" class="agent-workspace"><aside class="agent-threads"><div class="section-head"><div><h2>对话</h2><p>{{ agentThreads.length }} 个课程线程</p></div><button class="secondary" title="新建对话" @click="newAgentThread"><Plus :size="16"/> 新建</button></div><button v-for="thread in agentThreads" :key="thread.id" class="agent-thread" :class="{active:activeThread?.id===thread.id}" @click="activeThread=thread; api<AgentMessage[]>(`agent/threads/${thread.id}/messages/`).then(value=>agentMessages=value)"><MessageSquare :size="15"/><span>{{ thread.title }}</span></button><div v-if="!agentThreads.length" class="agent-empty">还没有对话</div></aside><div class="agent-chat"><div v-if="!activeThread" class="empty"><MessageSquare :size="34"/><h2>开始课程 Agent 对话</h2><p>可以直接提问，也可以让 Agent 参考本课程资料。</p><button class="primary" @click="newAgentThread">新建对话</button></div><template v-else><div class="agent-chat-head"><div><h2>{{ activeThread.title }}</h2><p>课程垂域 Agent · 支持流式回答与文件理解</p></div><div class="agent-actions"><button class="secondary" @click="createAgentArtifact('pdf')"><FileText :size="16"/> PDF</button><button class="secondary" @click="createAgentArtifact('docx')"><FileText :size="16"/> Word</button></div></div><div class="agent-messages"><article v-for="item in agentMessages" :key="item.id" class="agent-message" :class="item.role"><div class="agent-role">{{ item.role==='user'?'你':item.role==='assistant'?'Agent':'工具' }}</div><div class="agent-content">{{ item.content }}<div v-if="item.citations?.length" class="citations"><div v-for="(citation,index) in item.citations" :key="citation.chunk_id" class="citation"><strong>[{{ index+1 }}] {{ citation.title }} · 第 {{ citation.chunk_index + 1 }} 片</strong><span>{{ citation.excerpt.slice(0, 180) }}{{ citation.excerpt.length > 180 ? '…' : '' }}</span><a :href="citation.download_url" target="_blank"><ExternalLink :size="13"/> 打开资料</a></div></div></div></article><article v-if="agentStreaming" class="agent-message assistant"><div class="agent-role">Agent</div><div class="agent-content streaming">{{ agentStreaming }}<span class="cursor"></span></div></article></div><div class="agent-composer"><div class="agent-options"><label class="check"><input v-model="agentUseMaterials" type="checkbox"> 参考课程资料</label><label class="attach-button" title="添加附件"><Paperclip :size="16"/><input type="file" accept=".txt,.md,.pdf,.docx,image/*" @change="agentFileFrom">{{ agentFile ? agentFile.name : '添加附件' }}</label><button v-if="agentBusy" class="secondary" @click="stopAgent"><Square :size="15"/> 停止</button></div><textarea v-model="agentDraft" rows="3" placeholder="输入问题，或让 Agent 生成一份课程文档" @keydown.enter.exact.prevent="sendAgent"></textarea><button class="primary send-button" :disabled="agentBusy || !agentDraft.trim()" @click="sendAgent"><Send :size="16"/> {{ agentBusy ? '生成中…' : '发送' }}</button></div></template></div></section>
        <section v-if="tab==='materials'"><div class="section-head"><div><h2>课程资料</h2><p>课程成员可以下载这些文件</p></div><button v-if="isTeacher" class="primary" @click="panel='material'"><Upload :size="17"/> 上传资料</button></div><div v-if="materials.length" class="list"><div v-for="m in materials" :key="m.id" class="list-row"><div class="file-icon"><FolderOpen :size="19"/></div><div class="row-copy"><strong>{{ m.title }}</strong><small>{{ m.attachment.name }} · {{ size(m.attachment.size) }} · {{ fmt(m.created_at) }}</small><small :class="m.index_status==='ready'?'index-ready':'index-failed'">{{ m.index_status==='ready'?'已建立知识索引':m.index_status==='failed'?'未建立索引：'+(m.index_error || '请重试'):'正在建立索引' }}</small></div><button class="icon-button" title="下载" aria-label="下载" @click="getFile(m.attachment)"><Download :size="18"/></button></div></div><div v-else class="empty"><FolderOpen :size="32"/><h2>暂无课程资料</h2></div></section>
        <section v-if="tab==='assignments'"><div class="section-head"><div><h2>作业</h2><p>查看要求与提交记录</p></div><button v-if="isTeacher" class="primary" @click="panel='assignment'"><Plus :size="17"/> 发布作业</button></div><template v-if="currentAssignment"><button class="back" @click="currentAssignment=null"><ChevronLeft :size="16"/> 返回作业列表</button><div class="assignment-detail"><h2>{{ currentAssignment.title }}</h2><p class="meta">截止 {{ fmt(currentAssignment.due_at) }} · {{ currentAssignment.allow_late?'允许迟交':'截止后不可提交' }} · 最多 {{ currentAssignment.max_file_size_mb }} MB</p><p class="description">{{ currentAssignment.description || '暂无说明' }}</p><button v-if="currentAssignment.attachment" class="file-link" @click="getFile(currentAssignment.attachment)"><Download :size="16"/> {{ currentAssignment.attachment.name }}</button><div v-if="!isTeacher" class="submission-area"><h3>提交作业</h3><div class="upload-line"><input type="file" @change="fileFrom($event,'submission')"><button class="primary" :disabled="busy" @click="submit"><Upload :size="16"/> 提交文件</button></div><p class="hint">支持 {{ currentAssignment.allowed_extensions.length?currentAssignment.allowed_extensions.join('、'):'doc、docx、pdf、zip 等常见格式' }}</p><h3>提交记录</h3><div v-for="v in currentAssignment.my_versions || []" :key="v.number" class="list-row"><div class="row-copy"><strong>第 {{ v.number }} 版 · {{ v.attachment.name }}</strong><small>{{ fmt(v.submitted_at) }} {{ v.is_late?'· 迟交':'' }}</small></div><button class="icon-button" title="下载" @click="getFile(v.attachment)"><Download :size="18"/></button></div><p v-if="!currentAssignment.my_versions?.length" class="muted">尚未提交</p></div><div v-else class="submission-area"><h3>学生提交</h3><div v-for="s in submissions" :key="s.student.id" class="student-row"><strong>{{ s.student.name }}</strong><small>{{ s.student.email }}</small><div v-for="v in s.versions" :key="v.number" class="version"><span>第 {{ v.number }} 版 · {{ fmt(v.submitted_at) }} {{ v.is_late?'· 迟交':'' }}</span><button @click="getFile(v.attachment)"><Download :size="16"/> {{ v.attachment.name }}</button></div></div><p v-if="!submissions.length" class="muted">暂无提交</p></div></div></template><div v-else-if="assignments.length" class="list"><button v-for="a in assignments" :key="a.id" class="list-row assignment-row" @click="openAssignment(a)"><div class="file-icon"><ClipboardList :size="19"/></div><div class="row-copy"><strong>{{ a.title }}</strong><small>截止 {{ fmt(a.due_at) }} · {{ a.allow_late?'允许迟交':'截止后关闭' }}</small></div><span class="row-arrow">›</span></button></div><div v-else class="empty"><ClipboardList :size="32"/><h2>暂无作业</h2></div></section>
        <section v-if="tab==='members'"><div class="section-head"><div><h2>课程成员</h2><p>{{ members.length }} 位成员</p></div></div><div class="list"><div v-for="m in members" :key="m.id" class="list-row"><div class="avatar small">{{ m.name.slice(0,1) }}</div><div class="row-copy"><strong>{{ m.name }}</strong><small>{{ m.email }}</small></div><span class="role">{{ m.role==='teacher'?'教师':'学生' }}</span></div></div></section>
      </template>
      <div v-if="message" class="notice" role="status">{{ message }}<button aria-label="关闭提示" @click="message=''">×</button></div>
    </main>
    <div v-if="panel!=='none'" class="modal-backdrop" @click.self="panel='none'"><div class="modal"><div class="modal-head"><h2>{{ {create:'创建课程',join:'加入课程',invite:'教师邀请码',material:'上传资料',assignment:'发布作业'}[panel] }}</h2><button aria-label="关闭" @click="panel='none'">×</button></div><form v-if="panel==='create'" @submit.prevent="createCourse"><label>课程名称<input v-model="courseName" required maxlength="120" autofocus></label><label>课程图标（可选）<input type="file" accept="image/png,image/jpeg,image/webp" @change="fileFrom($event,'icon')"></label><button class="primary full" :disabled="busy">创建课程</button></form><form v-if="panel==='join'" @submit.prevent="joinCourse"><label>课程码<input v-model="joinCode" required maxlength="12" placeholder="输入教师提供的课程码"></label><button class="primary full" :disabled="busy">加入课程</button></form><form v-if="panel==='invite'" @submit.prevent="redeem"><label>教师邀请码<input v-model="invite" required></label><button class="primary full" :disabled="busy">兑换</button></form><form v-if="panel==='material'" @submit.prevent="uploadMaterial"><label>资料标题<input v-model="materialTitle" placeholder="留空则使用文件名"></label><label>文件<input type="file" required @change="fileFrom($event,'material')"></label><button class="primary full" :disabled="busy">上传资料</button></form><form v-if="panel==='assignment'" @submit.prevent="publish"><label>作业标题<input v-model="assignmentTitle" required maxlength="200"></label><label>作业说明<textarea v-model="description" rows="3"></textarea></label><label>截止时间<input v-model="dueAt" type="datetime-local" required></label><label>允许格式（逗号分隔，留空为全部常见格式）<input v-model="extensions" placeholder="doc,docx,pdf,zip"></label><label>单文件上限（MB）<input v-model.number="maxMb" type="number" min="1" max="50"></label><label>题目附件（可选）<input type="file" @change="fileFrom($event,'assignment')"></label><label class="check"><input v-model="allowLate" type="checkbox"> 允许迟交</label><button class="primary full" :disabled="busy">发布作业</button></form></div></div>
  </div>
</template>
